 dict(name="screen",ar="16:9",res="2K",q="high",p="The giant screen of a stock exchange trading floor seen perfectly straight on, orthographic: a thick black riveted steel bezel with antique-brass corner brackets and two brass hanging chains at the top, a thin green light strip along its inside left edge and a red one along its inside right edge; below the bezel, attached to it, a wide plain empty brass nameplate as wide as half the screen, completely blank. The whole screen glass inside the bezel is perfectly flat uniform pure magenta (#FF00FF). The screen with its nameplate spans from 5% to 95% of the image width and from 4% to 96% of the height."+MG),
 dict(name="mon",ar="1:1",res="1K",q="high",p="One small square broadcast monitor of a trading floor seen perfectly straight on, orthographic: a chunky black steel housing with rounded corners and four brass screws, the screen glass inside it perfectly flat uniform pure magenta (#FF00FF), and under the screen a small plain empty brass label plate, completely blank. The monitor spans from 12% to 88% of the width and from 8% to 92% of the height."+MG),
 dict(name="gplate",ar="16:9",res="1K",q="high",p="One single small square-ish brass grade plate, like a museum label tile, seen perfectly straight on, orthographic: polished antique brass with a bevelled raised edge and four tiny screws in the corners, its flat face completely blank. The plate spans from 34% to 66% of the image width and from 22% to 78% of the height."+MG),
