json.dump([{"name":j["name"],"model":"gpt-image-2","refs":R,"input":{"aspect_ratio":j["ar"],"resolution":j["res"],"quality":j["q"],"num_outputs":1,"prompt":j["p"]+ST}} for j in J],open('jobs1.json','w'),indent=0)
